'use strict';
let libraryTab='choices',guideQuery='',guideCar='',catalogueManagerQuery='',catalogueManagerCategory='',catalogueManagerMaker='',catalogueManagerScope='all',catalogueManagerSelected=new Set(),workshopLibraryContext='';
function guideFileSize(bytes){return bytes>=1024*1024?(bytes/1024/1024).toFixed(1)+' MB':(bytes/1024).toFixed(1)+' KB';}
function libraryContext(){const key=source+'|'+db.id;if(key!==workshopLibraryContext){workshopLibraryContext=key;catalogueManagerSelected.clear();guideCar='';}}
function libraryTabs(){return '<div class="tabs">'+[['choices','Reusable choices','library'],['parts','Parts catalogue','box']].map(([id,label,ic])=>`<button data-action="library-tab" data-id="${id}" class="${libraryTab===id?'active':''}">${icon(ic)}${label}</button>`).join('')+'</div>';}
function renderGuides(){
 libraryContext();const docs=db.documents.filter(d=>d.guide),cars=db.cars,total=db._view?.list?.total??docs.length;
 return heading('Manuals and Part Guides','Exploded views, part numbers and reference catalogues.',btn(icon('plus')+' Add guide','guide-add','primary'))+toolboxTabs()+`<div class="toolbar"><label class="search">${icon('search')}<input id="guide-search" aria-label="Search guides" placeholder="Search names or filenames…" value="${esc(guideQuery)}"></label><label class="field">Applies to<select id="guide-car-filter"><option value="">All guides</option><option value="general" ${guideCar==='general'?'selected':''}>General reference library</option>${cars.map(c=>`<option value="${esc(c.id)}" ${guideCar===c.id?'selected':''}>${esc(c.name)}${c.archived?' · Archived':''}</option>`).join('')}</select></label><span class="muted tiny">${total} guide${total===1?'':'s'}</span></div>`+(docs.length?`<div class="guide-gallery">${docs.map(d=>`<article class="guide-card"><button class="guide-poster" data-action="guide-open" data-id="${esc(d.id)}" aria-label="Open ${esc(d.title)}">${d.picture?`<img src="${esc(thumbnailSource(d.picture))}" alt="${esc(d.title)}" loading="lazy">`:`<span class="guide-pdf">${icon('library')}<strong>PDF</strong><span>${esc(d.title)}</span></span>`}<span class="guide-open-label">Open ${d.mime==='application/pdf'?'PDF':'image'} ↗</span></button><div class="guide-card-details"><h2>${esc(d.title)}</h2><p class="muted">${esc(cars.find(c=>c.id===d.carId)?.name||'General reference library')}</p><p class="tiny muted">${esc(d.name)} · ${guideFileSize(d.size)}</p><div class="actions">${btn('Edit details','guide-edit','small',d.id)}${btn('Export copy','export-document','small',d.id)}${btn('Remove…','guide-remove','small danger',d.id)}</div></div></article>`).join('')}</div>`:empty(guideQuery||guideCar?'No matching guides':'Your reference wall','Add an image or PDF, give it a name, and choose a car or General reference library.',btn('Add guide','guide-add','primary')))+viewPager(db._view?.list)+'<p class="footer-note">Click a poster to open the original in your default image or PDF app. Originals are stored unchanged in this collection and included in complete backups. Up to 20 MiB per file; Dealership uploads must fit the 16 MiB encoded review limit. External edits do not change the saved original.</p>';
}
async function editGuide(id){
 const existing=id?db.documents.find(d=>d.id===id&&d.guide):null,revision=db.revision,databaseId=db.id;
 if(id&&!existing)throw Error('Guide not found.');
 const picked=existing?null:await api('file','guide.pick');if(!existing&&!picked)return;
 if(db.id!==databaseId)throw Error('The collection changed. Add the guide again.');
 const doc=existing||picked.document;
 modal(existing?'Edit guide details':'Add manual or part guide',`<p class="muted">${esc(doc.name)} · ${guideFileSize(doc.size)}</p><div class="form-grid"><label class="field wide">Guide name<input name="title" maxlength="200" required value="${esc(existing?.title||doc.name.replace(/\.[^.]+$/,''))}"></label><label class="field wide">Car<select name="carId"><option value="">General reference library</option>${db.cars.map(c=>`<option value="${esc(c.id)}" ${existing?.carId===c.id?'selected':''}>${esc(c.name)}${c.archived?' · Archived':''}</option>`).join('')}</select></label></div><p class="muted mt">Use General reference library for manufacturer catalogues or instructions shared by several cars.</p>`,async values=>change(existing?'guide.edit':'guide.add',{id,revision,title:values.title,carId:values.carId||null,...(picked?{document:picked.document,picture:picked.picture}:{})}),existing?'Save details':'Add guide');
}
function removeGuide(id){const d=db.documents.find(d=>d.id===id&&d.guide),revision=db.revision;if(!d)throw Error('Guide not found.');modal('Remove guide?',`<p>Remove <strong>${esc(d.title)}</strong> from this collection? The original file on your computer and earlier backups are unchanged.</p>`,async()=>change('guide.remove',{id,revision}),'Remove guide');}
function renderCatalogueManager(){
 if(!local())return empty('Catalogue management is local','Choose your own collection to manage its parts.');libraryContext();
 const parts=db.parts,total=db._view?.list?.total??parts.length,makers=db._view?.catalogueMakers||[...new Set(parts.map(p=>p.maker).filter(Boolean))];
 return heading('Parts catalogue','Manage product entries and remove unused references.',btn('Add catalogue entry','catalogue-manager-add','primary'))+libraryTabs()+`<div class="toolbar"><label class="search">${icon('search')}<input id="catalogue-manager-search" aria-label="Search catalogue" placeholder="Search parts, references or manufacturers…" value="${esc(catalogueManagerQuery)}"></label>${categorySelect('catalogue-manager-category','Main group',catalogueManagerCategory,Object.keys(slotforgeCatalogue.parts),true)}<label class="field">Manufacturer<select id="catalogue-manager-maker"><option value="">All manufacturers</option>${makers.map(m=>`<option value="${esc(m)}" ${m===catalogueManagerMaker?'selected':''}>${esc(m)}</option>`).join('')}</select></label><label class="field">Entries<select id="catalogue-manager-scope">${[['all','All entries'],['unowned','Not owned'],['owned','Owned stock']].map(([id,label])=>`<option value="${id}" ${id===catalogueManagerScope?'selected':''}>${label}</option>`).join('')}</select></label></div><div class="catalogue-manager-bar"><span>${total} part record${total===1?'':'s'}</span><div class="actions">${btn('Select this page','catalogue-manager-select-page','small')}${catalogueManagerSelected.size?badge(catalogueManagerSelected.size+' selected')+btn('Clear selection','catalogue-manager-clear','small')+btn('Review deletion…','catalogue-manager-delete-selected','small danger'):''}</div></div>`+(parts.length?`<div class="table-wrap"><table class="catalogue-manager-table"><thead><tr><th><span class="muted">Select</span></th><th>Part / reference</th><th>Manufacturer</th><th>Group / type</th><th>Owned</th><th>Manage</th></tr></thead><tbody>${parts.map(p=>`<tr><td><input type="checkbox" data-catalogue-select="${esc(p.id)}" aria-label="Select ${esc(p.name)}" ${catalogueManagerSelected.has(p.id)?'checked':''}></td><td><button class="table-name" data-action="catalogue-manager-open" data-id="${esc(p.id)}">${esc(p.name)}</button><div class="tiny muted">${esc(p.reference||'No reference')}</div></td><td>${esc(p.maker||'—')}</td><td>${esc(p.category)}<div class="tiny muted">${esc(p.partType)}</div></td><td>${p.quantity}</td><td><div class="actions">${btn('Edit','edit-part','small',p.id)}${btn('Delete…','delete-part','small danger',p.id)}</div></td></tr>`).join('')}</tbody></table></div>`:empty('No matching parts','Adjust the filters or add a catalogue entry.'))+viewPager(db._view?.list)+'<p class="footer-note">These are the same records used by Parts. Edits apply there too. Bulk deletion only removes unowned, unreferenced entries; linked stock and history are protected.</p>';
}
async function deleteCatalogueSelection(){const plan=await api('plan','part.deleteMany',{ids:[...catalogueManagerSelected]});modal('Review catalogue deletion',`<p>${plan.eligible.length} unused, unowned entries can be deleted. ${plan.blocked.length} must be kept.</p>${plan.eligible.length?'<h3>Delete</h3><ul>'+plan.eligible.map(p=>'<li>'+esc(p.name)+'</li>').join('')+'</ul>':''}${plan.blocked.length?'<h3>Keep</h3><ul>'+plan.blocked.map(p=>'<li><strong>'+esc(p.name)+'</strong>: '+esc(p.reasons.join(', '))+'</li>').join('')+'</ul>':''}${plan.eligible.length?'<label class="check-row"><input type="checkbox" name="confirmed" required>Delete only the entries listed under Delete.</label>':''}`,plan.eligible.length?async values=>{await change('part.deleteMany',{ids:plan.eligible.map(p=>p.id),revision:plan.revision,confirmed:!!values.confirmed});catalogueManagerSelected.clear();}:null,'Delete unused entries');}
async function workshopLibraryAction(action,id){switch(action){
 case 'library-tab':if(!['choices','parts'].includes(id))return true;libraryTab=id;if(id==='choices')await loadChoices();render();return true;
 case 'guide-add':await editGuide();return true;
 case 'guide-edit':await editGuide(id);return true;
 case 'guide-remove':removeGuide(id);return true;
 case 'guide-open':await api('file','document.open',{id});return true;
 case 'catalogue-manager-add':editPart();$('#dialog [name=quantity]').value='0';return true;
 case 'catalogue-manager-open':page='Parts';partsTab='Stock';stockScope='catalogue';partId=id;partCategory='';partQuery='';partTypeFilter='';render();return true;
 case 'catalogue-manager-select-page':if(new Set([...catalogueManagerSelected,...db.parts.map(p=>p.id)]).size>200){toast('Select up to 200 entries at a time.',true);return true;}db.parts.forEach(p=>catalogueManagerSelected.add(p.id));render();return true;
 case 'catalogue-manager-clear':catalogueManagerSelected.clear();render();return true;
 case 'catalogue-manager-delete-selected':await deleteCatalogueSelection();return true;
 }return false;}
document.addEventListener('input',e=>{if(e.target.id==='guide-search'){guideQuery=e.target.value;scheduleView();}if(e.target.id==='catalogue-manager-search'){catalogueManagerQuery=e.target.value;catalogueManagerSelected.clear();scheduleView();}});
document.addEventListener('change',e=>{const el=e.target;let changed=true;if(el.id==='guide-car-filter')guideCar=el.value;else if(el.id==='catalogue-manager-category')catalogueManagerCategory=el.value;else if(el.id==='catalogue-manager-maker')catalogueManagerMaker=el.value;else if(el.id==='catalogue-manager-scope')catalogueManagerScope=el.value;else if(el.dataset.catalogueSelect){if(el.checked&&catalogueManagerSelected.size>=200){el.checked=false;toast('Select up to 200 entries at a time.',true);return;}el.checked?catalogueManagerSelected.add(el.dataset.catalogueSelect):catalogueManagerSelected.delete(el.dataset.catalogueSelect);render();return;}else changed=false;if(changed){catalogueManagerSelected.clear();render();}});
